dual_clock.sv.source:
module dual_clock(input logic clk_a, clk_b, input logic [7:0] d_a, d_b,
                  output logic [7:0] q_a, q_b);
  always_ff @(posedge clk_a) q_a <= d_a;
  always_ff @(posedge clk_b) q_b <= d_b;
endmodule

signed_div.sv.source:
module signed_div(input logic signed [7:0] a, b, output logic signed [7:0] q);
  assign q = a / b;
endmodule

const_only.sv.source:
module const_only(output logic [7:0] y);
  assign y = 8'h2a;
endmodule
